INSERT INTO `spa_config` VALUES (1,'title','Spa. Estetica. Centros de Estética. Centros Integrales de Estética y Medicina, Tratamientos de Estetica. Estilo Spa'),(2,'description','EstiloSpa, El Portal lider en promocionar Spa, centros de Estetica, Centros de Medicina Estetica, Centros de Belleza, Clinica. Cumple 8 Años online, desde sus inicios, trabaja promocionando y dando a conocer a todos los cibernautas, las diferentes opciones en spa, Centros de Estetica; Centros de Belleza; Medicina Estetica, clinicas, Masajes; todo lo relacionado con el Relax, Bienestar y la Estetica Facial y Corporal.'),(3,'phones','[\"011 4643 0556\"]'),(4,'mails','[\"estilospa.com@gmail.com\"]'),(5,'keywords','Spa, estetica, medicina, cirugia, masajes, tratamientos, centros de estetica, medicina estetica, cirugia estetica, masajes, tratamientos faciales, tratamientos corporales'),(6,'maintenance','0');
