INSERT INTO `spa_features` VALUES (2075,38,'Descripción','<p>Un espacio de salud, belleza y bienestar que cuenta con los mejores tratamientos est&eacute;ticos,&nbsp;&nbsp; tecnolog&iacute;a de&nbsp; vanguardia&nbsp; y&nbsp; profesionales&nbsp; altamente capacitados para brindarte la mejor atenci&oacute;n.<br />\n<br />\nEn HILDARA cada paciente recibe&nbsp; asesoramiento dermatol&oacute;gico, y&nbsp; todos los procedimientos est&aacute;n&nbsp; acompa&ntilde;ados de un constante y estricto seguimiento m&eacute;dico.<br />\n<br />\nBas&aacute;ndose en&nbsp; pilares fundamentales, tales como: atenci&oacute;n personalizada, profesionalidad, responsabilidad, compromiso y calidez, HILDARA ofrece los siguientes tratamientos:</p>\n\n<p><strong>PRIMERA CONSULTA SIN CARGO</strong></p>\n',1),(2076,38,'Tratamientos Faciales','<ul>\n	<li>Mesolifting - Mesoglow</li>\n	<li>Lifting biol&oacute;gico</li>\n	<li>Toxina botul&iacute;nica (BOTOX&reg;)</li>\n	<li>Rellenos o implantes (&Aacute;cido Hialur&oacute;nico)</li>\n	<li>Plasma rico en plaquetas</li>\n	<li>Peeling qu&iacute;mico</li>\n	<li>Puntas de diamante</li>\n	<li>L&aacute;ser de Diodo</li>\n	<li>Radiofrecuencia</li>\n	<li>Electroporaci&oacute;n</li>\n</ul>\n',2),(2077,38,'Tratamientos Corporales','<ul>\n	<li>Electroestimulaci&oacute;n (Ondas Rusas e Interferenciales)</li>\n	<li>Plasma rico en plaquetas</li>\n	<li>Peeling qu&iacute;mico</li>\n	<li>Puntas de diamante</li>\n	<li>Radiofrecuencia</li>\n	<li>Mesoterapia</li>\n	<li>Electroporaci&oacute;n</li>\n	<li>Ultracavitaci&oacute;n</li>\n	<li>Presoterapia secuencial</li>\n	<li>L&aacute;ser de Diodo</li>\n</ul>\n',3),(2078,38,'Tratamientos Capilares','<p>Ca&iacute;da de cabello&nbsp; y fragilidad capilar: Las estrategias con mayores resultados, requieren de un diagn&oacute;stico m&eacute;dico oportuno, a fin de restablecer el equilibrio tisular, qu&iacute;mico y biol&oacute;gico del organismo.<br />\n&nbsp;</p>\n\n<ul>\n	<li>Mesoterapia capilar</li>\n	<li>Plasma rico en Plaquetas</li>\n	<li>Complementos y Nutrici&oacute;n Orthomolecular</li>\n	<li>Calor inducido &ndash; Termoterapia</li>\n	<li>Alta Frecuencia</li>\n</ul>\n',4),(2079,38,'Láser de Diodo','<p>L&Aacute;SER DE DIODO synus&reg;: Manejado s&oacute;lo por personal m&eacute;dico especializado</p>\n\n<p>&nbsp;</p>\n\n<ul>\n	<li>Rejuvenecimiento facial y corporal</li>\n	<li>Lesiones pigmentadas (manchas)</li>\n	<li>Tatuajes oscuros</li>\n	<li>Telangiectasias (ara&ntilde;itas)</li>\n	<li>Fotodepilaci&oacute;n</li>\n</ul>\n',5),(2080,38,'Terapias de SPA','<ul>\n	<li>Tratamientos integrales de relax, salud y cuidado de la piel.</li>\n	<li>Spa facial&nbsp; HILDARA</li>\n	<li>Spa corporal HILDARA</li>\n	<li>Spa facial Gold</li>\n	<li>Masaje capilar</li>\n	<li>Chocolaterapia</li>\n	<li>Pulidos&nbsp; faciales y corporales</li>\n	<li>Hidrataci&oacute;n profunda</li>\n	<li>Fangoterapia</li>\n	<li>Spa de manos y pies</li>\n	<li>Belleza de manos y pies</li>\n	<li>D&iacute;a de spa</li>\n	<li>Men Day Spa</li>\n	<li>D&iacute;a de la novia</li>\n	<li>Spa San Valent&iacute;n</li>\n	<li>Drenaje linf&aacute;tico manual</li>\n	<li>Masajes relajantes-bamb&uacute;</li>\n	<li>Masajes relajantes-piedras calientes</li>\n	<li>Masajes descontracturantes</li>\n	<li>Ducha escocesa.</li>\n</ul>\n',6),(2081,38,'Dermatología Estética','<ul>\n	<li>Ca&iacute;da de cabello</li>\n	<li>Ros&aacute;cea</li>\n	<li>Arrugas</li>\n	<li>Fotoda&ntilde;o</li>\n	<li>Hiperpigmentaci&oacute;n</li>\n	<li>Cicatrices</li>\n	<li>Acn&eacute;</li>\n	<li>Estr&iacute;as</li>\n	<li>Flacidez</li>\n	<li>Celulitis(P.E.F.E)</li>\n</ul>\n',7),(2082,38,'Nutrición','<ul>\n	<li>Asesoramientos personalizados</li>\n	<li>Planes de desintoxicaci&oacute;n</li>\n	<li>Planes de alimentaci&oacute;n natural</li>\n	<li>Planes de descenso de peso</li>\n	<li>Valoraci&oacute;n del estado nutricional- Antropometr&iacute;a</li>\n	<li>Seguimiento nutricional</li>\n</ul>\n',8),(2083,38,'Más Servicios','<p>TRATAMIENTOS PARA EMBARAZADAS</p>\n\n<ul>\n	<li>Limpieza facial</li>\n	<li>Masajes relajantes</li>\n	<li>Drenaje Linf&aacute;tico Manual</li>\n	<li>Hidrataci&oacute;n facial y corporal</li>\n	<li>Exfoliaciones faciales y corporales</li>\n	<li>Asesoramiento Dermatol&oacute;gico</li>\n</ul>\n\n<p>&nbsp;</p>\n\n<p>TRATAMIENTOS POST PARTO</p>\n\n<ul>\n	<li>Contamos con numerosos tratamientos m&eacute;dico est&eacute;ticos que ayudan y aceleran la recuperaci&oacute;n del cuerpo y la piel luego del embarazo.</li>\n</ul>\n\n<p><br />\nTRATAMIENTOS PARA HOMBRES</p>\n\n<ul>\n	<li>Tratamientos capilares</li>\n	<li>Tratamientos faciales</li>\n	<li>Tratamientos corporales</li>\n	<li>Men Day Spa</li>\n</ul>\n\n<p>&nbsp;</p>\n\n<p>PARA REGALAR</p>\n\n<ul>\n	<li>En ese d&iacute;a tan especial regal&aacute; un &ldquo;Voucher de Obsequio HILDARA&rdquo;</li>\n</ul>\n\n<p>&nbsp;</p>\n\n<p>D&Iacute;AS ESPECIALES</p>\n\n<ul>\n	<li>Voucher Fel&iacute;z D&iacute;a Mam&aacute;</li>\n	<li>Voucher Fel&iacute;z D&iacute;a Pap&aacute;</li>\n	<li>Voucher San Valent&iacute;n</li>\n	<li>Voucher Friend&acute;s Day</li>\n</ul>\n\n<p>&nbsp;</p>\n\n<p>PLANES ESPECIALES</p>\n\n<ul>\n	<li>Plan novia radiante</li>\n	<li>Preparate para tu boda</li>\n	<li>Preparate para tus 15</li>\n</ul>\n\n<p>&nbsp;</p>\n\n<p>SERVICIOS PARA EMPRESAS</p>\n\n<ul>\n	<li>Beneficios para empresas</li>\n	<li>Regalos empresariales</li>\n</ul>\n',9),(2201,57,'Descripción','<p>L.est&eacute;tica es un espacio dedicado especialmete al cuidado de la mujer ofreciendo un servicio de categor&iacute;a, donde la atenci&oacute;n, el seguimiento y tu comodidad son nuestra misi&oacute;n. Como estuvimos en tu lugar sabemos lo dif&iacute;cil que a veces se hace poder acceder a un tratamiento de estas caracteristicas, por esto te ofrecemos ademas el mejor costo que existe en este tipo de servicios. Cuando pensamos en este proyecto quisimos transmitirte que sabemos lo que necesit&aacute;s; porque tenemos tus mismas necesidades. Contamos con la tecnolog&iacute;a adecuada para cada caso y un precio totalmente accesible para que resaltes tu belleza... porque primero estas vos y nosotras estamos para ayudarte...</p>\n',1),(2202,57,'TRATAMIENTOS FACIALES','<p>Conoc&eacute; nuestros tratamientos<br />\nsus tecnolog&iacute;as y como act&uacute;an sobre el cuerpo logrando resultados incre&iacute;bles</p>\n\n<ul>\n	<li>Consulta y diagn&oacute;stico sin cargo</li>\n	<li>Crioradiofrecuencia, congel&aacute; el paso del tiempo</li>\n	<li>Peeling Mec&aacute;nico: Microdermoabrasion con puntas de diamantes</li>\n	<li>Peeling Cosmetol&oacute;gico - Qu&iacute;mico - Manchas</li>\n	<li>Limpieza Profunda con m&aacute;scaras especiales</li>\n	<li>Tratamientos Antiage</li>\n	<li>Shock para Fiestas</li>\n	<li>Asesoramiento en apoyo domiciliario</li>\n</ul>\n',2),(2203,57,'TRATAMIENTOS CORPORALES','<p>Conoc&eacute; nuestros tratamientos<br />\nsus tecnolog&iacute;as y como act&uacute;an sobre el cuerpo logrando resultados incre&iacute;bles</p>\n\n<ul>\n	<li>Diagn&oacute;stico y consulta sin cargo</li>\n	<li>HImFU Ultracavitacion 2.9 de alta frecuencia multifocal</li>\n	<li>Criolipolisis 50% OFF</li>\n	<li>Dermohealth + Leds Laser</li>\n	<li>Crioradiofrecuencia, reduci&oacute;m, tensado y celulitis</li>\n	<li>TermocellStim 2 tratamientos en uno!</li>\n	<li>Lipolaser, reducci&oacute;n general, hasta 8 zonas por sesi&oacute;n!</li>\n	<li>Termolipolisis</li>\n	<li>Ondas Rusas</li>\n	<li>Ondas Interferenciales</li>\n	<li>Electrodos</li>\n	<li>Vendas Fr&iacute;as</li>\n	<li>Ultrasonido post-operatorio</li>\n	<li>Botas de Presoterapia</li>\n	<li>Puntas de Diamantes</li>\n	<li>Masajes descontracturantes, relajantes y reductores.</li>\n	<li>Asesoramiento en apoyo domiciliario</li>\n</ul>\n',3),(2204,57,'Depilación Soprano','<p><strong>R&aacute;pida, eficaz y virtualmente indolora</strong></p>\n\n<p>Soprano es el sistema de depilaci&oacute;n l&aacute;ser m&aacute;s eficaz y completo que existe hoy en el mercado, para todo tipo de piel y pelo.</p>\n\n<p>Soprano es el sistema de depilaci&oacute;n definitiva de elecci&oacute;n en Europa y USA, y el segundo procedimiento est&eacute;tico m&aacute;s demandado del Mundo. En la mayor&iacute;a de los casos se elimina hasta 60% del vello en la primer sesi&oacute;n.</p>\n\n<p><br />\nSe trata de una nueva t&eacute;cnica desarrollada por Alma Lasers, que depila en forma r&aacute;pida, eficaz y virtualmente indolora, aplicable a todo tipo de piel y de vello.<br />\nActualmente es el &uacute;nico sistema que permite depilar en verano, en pieles reci&eacute;n bronceadas y oscuras, con total seguridad y sin efectos secundarios ni dolor.</p>\n\n<p><br />\nUna combinaci&oacute;n de tecnolog&iacute;as hace posible un tratamiento indoloro y sumamente eficaz. El l&aacute;ser de diodo de alta potencia y onda continua trabaja en conjunto con el modo SHR. Esta novedosa tecnolog&iacute;a, exclusiva de Soprano, remueve el vello &quot;en movimiento y en forma progresiva&quot; a partir de una t&eacute;cnica de barrido, eliminando el problema de puntos o zonas no tratadas.<br />\nSoprano, brinda resultados &oacute;ptimos a partir del calentamiento progresivo de la dermis hasta una temperatura que elimina el fol&iacute;culo en forma permanente y previene la reaparici&oacute;n, sin necesidad de analg&eacute;sicos o sistemas de enfriamiento extra.<br />\nExcelentes resultados cl&iacute;nicos, sumados al m&aacute;s alto confort del paciente, hacen que Soprano sea la soluci&oacute;n &oacute;ptima para la depilaci&oacute;n l&aacute;ser definitiva.<br />\nEs seguro y efectivo para todos los tipos de piel y de vello y permite que el paciente se reincorpore a sus actividades cotidianas de manera inmediata, ya que no presenta efectos colaterales frecuentes en los tratamientos cl&aacute;sicos, como enrojecimiento, irritaci&oacute;n o manchas.</p>\n\n<p>- Cuidados post sesi&oacute;n: Tratar de no exponerse al sol durante las 48hs posteriores a la sesi&oacute;n y utilizar bloqueador solar total.</p>\n\n<p>- Frecuencia recomendada: En general promedio es de 8 a 10 sesiones. al principio cada 30 d&iacute;as y a medida que avanza el tratramiento se deben espaciar cada 90 d&iacute;as o m&aacute;s. Excepcionalmente, las primeras sesiones faciales se pueden realizar con m&aacute;s frecuencia, cada 20 d&iacute;as.</p>\n',4),(2205,57,'Servicios','<p><strong>Permanente y Tintura de Pesta&ntilde;as</strong><br />\nLuc&iacute; una mirada &uacute;nica e impactante con Permanente y tintura de pesta&ntilde;as!! No s&oacute;lo las arqueamos, sino que adem&aacute;s las te&ntilde;imos para lograr as&iacute; unas pesta&ntilde;as perfectas sin maquillarte!!<br />\n<br />\n<strong>Extensiones de Pesta&ntilde;as pelo por pelo</strong><br />\nLas extensiones de pesta&ntilde;as es un sistema en el cual se coloca pelo por pelo una pesta&ntilde;a sobre cada una de las pesta&ntilde;as propias, aumentando as&iacute; el largo y el volumen propio, logrando un aspecto natural, sensual o tupido.<br />\nUtilizamos Blink, la mejor marca del mercado, que no deterioran tus pesta&ntilde;as naturales.</p>\n',5),(2294,37,'Descripción','<p>En Belle Body te ayudamos a mantener el equilibrio fundamental de tu vida, a que te sientas y te veas bien con tu cuerpo, te brindamos asesoramiento profesional y responsable.<br />\n<br />\nEncontrar&aacute;s opciones para encontrar la armon&iacute;a de tu&nbsp; cuerpo con&nbsp; tratamientos corporales y faciales, masajes, y otros servicios especiales.<br />\n<br />\nTe invitamos a conocer m&aacute;s sobre nuestros tratamientos y terapias,&nbsp; en nuestro sitio web. No dudes en contactarnos para ofrecerte atenci&oacute;n personalizada.<br />\n<br />\n<strong>Un lugar para verte y sentirte bien...</strong></p>\n',1),(2295,37,'SPA','<p><strong>&middot; Gourmet spa</strong><br />\nSensaciones &uacute;nicas con resultados excepcionales:<br />\nPurify: pulido corporal con mouse exfoliante de vainilla y coco<br />\nRelax &amp; calm: masaje descontracturante x 40 min. con crema de masajes chocolate y almendras dulces<br />\nRevitalize: Mascara corporal de cafe y cacao.</p>\n\n<p><strong>&middot; Exotic spa</strong><br />\nUn camino milenario de espiritualidad y relajacion:<br />\nPurify: pulido corporal con exfoliante purificante del tibet azucar y lemongrass<br />\nRelax &amp; calm: masaje descontracturante x 40 min. con aceite de&nbsp; canela y kummel<br />\nRevitalize:Mascara corporal antiage himalaya Gengibre y rosa galica.<br />\nLimipieza facial: con shock de vitamina c . iluminaci&oacute;n instant&aacute;nea de tu piel.</p>\n\n<p>&nbsp;</p>\n\n<p><strong>&middot; Amazon spa</strong><br />\nInspirado en el amazonas, fuente de energia, pureza y naturaleza:<br />\nPurify: pulido corporal con mascara exfoliante enzim&aacute;tica de papaya y mango<br />\nRelax y calm: Hidratacion corporal con fango natural amazonico oxigenante y detoxificante<br />\nRevitaliza: Masaje con velas de Guayaba y pitanga amarella.</p>\n\n<p>&nbsp;</p>\n\n<p><strong>MINI SPA</strong></p>\n\n<ul>\n	<li>Masaje descontracturante x 40 minutos + limpieza facial con shock de vitamina c</li>\n	<li>Pulido corporal + hidrataci&oacute;n con algoterapia + Masaje descontracturante</li>\n	<li>Masaje descontracturante de espalda, piernas y pies x 1 hs + presoterapia (drenaje linf&aacute;tico mecanico) &nbsp;</li>\n	<li>Presoterapia (drenaje linf&aacute;tico mec&aacute;nico) + limpieza facial con mascara super hidratante y antifatiga</li>\n	<li>Limpieza facial + pulido corporal +hidrataci&oacute;n +&nbsp; drenaje linf&aacute;tico manual.</li>\n</ul>\n\n<p>&nbsp;</p>\n\n<p><strong>&middot; Spa Belle Body:</strong><br />\nTodos los servicios para irte super relajada y linda:<br />\nMasaje descontracturante de espalda piernas y pies x 1 hs + presoterapia (drenaje linf&aacute;tico mec&aacute;nico) + Limpieza facial premium con mascara facial antiage caviar y oliva o mascara super hidratante y antifatiga.</p>\n\n<p>&nbsp;</p>\n\n<p><strong>Spa para dos: ( podes venir con una amiga en la misma sesion)</strong></p>\n\n<ul>\n	<li>Masaje descontracturante x 40 minutos + Presoterapia secuencial (drenaje linf&aacute;tico mec&aacute;nico)</li>\n	<li>Masaje descontracturante x 40 minutos + pulido corporal + hidrataci&oacute;n con algas y termoterapia.</li>\n	<li>Masaje descontracturante de pies a cabeza 1 hs + presoterapia secuencial &nbsp;</li>\n</ul>\n',2),(2296,37,'Tratamientos Corporales','<p><strong>Reductores</strong><br />\n&middot; Ultracavitacion 40khz (Cavicell) + presoterapia secuencial<br />\n&middot; Masajes reductores + algas + termolipolisis<br />\n<br />\n<strong>Celulitis</strong><br />\n&middot; Ultrasonido 3 mhz + ondas interferenciales<br />\n&middot; Presoterapia Secuencial<br />\n&middot; Drenaje linfatico manual (metodo Vooder)<br />\n<br />\n<strong>Flaccidez</strong><br />\n&middot; Electroestumulaci&oacute;n (ondas rusas) + genotherm (radiofrecuencia bipolar)<br />\n<br />\n<strong>Estrias</strong><br />\n&middot; Punta de diamantes + peeling con acidos+ serum irs 6 de idraet.</p>\n\n<p><br />\nTodos los tratamientos son personalizados y armados a la necesidad de cada paciente.<br />\nConsulta por nuestros paquetes promocionales.<br />\n1er consulta sin cargo.</p>\n',3),(2297,37,'Tratamientos Faciales','<ul>\n	<li>Limpieza facial.</li>\n	<li>Limpieza facial con extracciones.</li>\n	<li>Tratamiento antiage (plasma infusion lidherma-mascaras antiage, velo de colageno, etc).</li>\n	<li>Radiofrecuencia bipolar (lifting sin cirugia).</li>\n	<li>Pelling mecanico (punta de diamantes).</li>\n	<li>Peeling quimico (acidos madelico- salicilico-glicolico)</li>\n	<li>Peeling combinado.</li>\n	<li>Tratamiento rosacea.</li>\n	<li>Tratamiento acne.</li>\n	<li>Limpieza&nbsp; de espalda.</li>\n	<li>Permanente y tintura de pesta&ntilde;as, realizada co productos importados Thuya professional line.</li>\n</ul>\n',4),(2525,79,'Descripción','<p><strong>En Little Ranch Hotel Spa encontrar&aacute;s todo lo necesario para tu Relax.</strong></p>\n\n<p>Piscina al aire libre, piscina cubierta climatizada, 2 hidromasajes a distintas temperaturas, sauna seco a 80&rsquo; C y Sauna h&uacute;medo a 50 &ordm;, parque,&nbsp; Quinchos, camas paraguayas, reposeras, cancha de futbol 5, pool, metegol y ping pong.</p>\n',1),(2526,79,'Servicios','<p>Day Spa</p>\n\n<p>Day Spa Grupos</p>\n\n<p>Night Spa</p>\n\n<p>Day Spa con Alojamiento</p>\n\n<p>Tratamientos Individuales</p>\n',2),(3906,45,'Descripción','<p>Maison Barrag&aacute;n, abre las puertas para unir la Medicina Est&eacute;tica y Spa Urbano, creando un Universo de belleza y Armon&iacute;a externa e interna, en cada persona. Complementa la salud y el bienestar con un abordaje cl&iacute;nico y profesional en medicina, al mismo tiempo propone una mirada profunda y elegante llenando al SER de energ&iacute;as positivas, logrando infinidad de sensaciones.</p>\n',1),(3907,45,'Tratamientos Faciales','<ul>\n	<li>Higiene facial profunda</li>\n	<li>Nutrici&oacute;n o hidrataci&oacute;n</li>\n	<li>Ampolla de elastina o col&aacute;geno</li>\n	<li>M&aacute;scara tensora</li>\n	<li>Suero vitaminizado (vitamina c)</li>\n	<li>M&aacute;scaras, seg&uacute;n biotipo de piel</li>\n	<li>Radiofrecuencia</li>\n	<li>Botox&reg;</li>\n	<li>Acido hialur&oacute;nico</li>\n	<li>Lifting sin cirug&iacute;a</li>\n	<li>Dermoabrasi&oacute;n con punta de diamante</li>\n	<li>Peeling con &aacute;cidos de &uacute;ltima generaci&oacute;n, manchas</li>\n	<li>Plasma rico en plaquetas</li>\n</ul>\n',2),(3908,45,'Tratamientos Corporales','<ul>\n	<li>Tratamientos capilares</li>\n	<li>Depilaci&oacute;n definitiva l&aacute;ser</li>\n	<li>Mesoterapia</li>\n	<li>Lip&oacute;lisis qu&iacute;mica-fosfatidilcolina-</li>\n	<li>Ultracavitaci&oacute;n</li>\n	<li>Plasma rico en plaquetas</li>\n	<li>Microdermoabrasi&oacute;n</li>\n	<li>Peeling qu&iacute;micos</li>\n	<li>Radiofrecuencia</li>\n	<li>Ondas rusas</li>\n	<li>Presoterapia</li>\n	<li>Ultrasonido</li>\n	<li>Criolip&ograve;lisis</li>\n	<li>Drenaje linf&aacute;tico manual</li>\n</ul>\n',3),(3909,45,'Spa Urbano','<ul>\n	<li>Higiene facial profunda</li>\n	<li>Spa gourmet: vinoterapia, chocoterapia, fango terapia</li>\n	<li>Exfoliaci&oacute;n corporal</li>\n	<li>M&aacute;scara descongestiva</li>\n	<li>M&aacute;scara anti age</li>\n	<li>Sauna seco</li>\n	<li>Ba&ntilde;o de vapor</li>\n	<li>Ducha escosesa</li>\n	<li>Masaje express</li>\n	<li>Masajes descontracturantes</li>\n	<li>Masajes con piedras calientes</li>\n	<li>Masaje deportivo</li>\n	<li>Reflexologia hol&iacute;stica</li>\n	<li>Masaje shiatsu</li>\n	<li>Masajes reductores</li>\n	<li>Masaje con pindas arom&aacute;ticas</li>\n	<li>Masaje con ca&ntilde;as de bamb&uacute;</li>\n	<li>Camilla de masaje con piedras de jade</li>\n</ul>\n',4),(4052,69,'Descripción','<p>Somos un equipo de profesionales con vasta experiencia y trayectoria, con el fin de brindar a nuestros clientes la atenci&oacute;n personalizada y el asesoramiento profesional que se merecen. Nuestra actualizaci&oacute;n constante y aparatolog&iacute;a de vanguardia nos permiten ofrecer los m&aacute;s novedosos tratamientos corporales y faciales dedicados al cuidado integral de la mujer.<br />\nTe propongo que descubras un lugar donde puedas sentirte bien con vos misma. Un espacio dedicado al cuidado de tu salud y tu belleza, en el que encontrar&aacute;s una variada propuesta de tratamientos personalizados pensados a tu medida. Quiero brindarte la excelencia profesional de mi equipo combinada con la m&aacute;s alta tecnolog&iacute;a y los mejores productos cosm&eacute;ticos. Verte mejor empieza por vos y me gustar&iacute;a poder ayudarte . Te esperamos!!!</p>\n\n<p>Promos Para Mam&aacute;</p>\n\n<p>Valeria Di Giorno</p>\n',1),(4053,69,'Tratamientos Corporales','<p>- Criolip&oacute;lisis<br />\n- Ulthera (HIFU)<br />\n- Velaslim (celulitis, flaccidez y adiposidad localizada)<br />\n- Termocell Stim (modelaci&oacute;n corporal)<br />\n- Electroestimulaci&oacute;n (tonificaci&oacute;n)<br />\n- Presoterapia (drenaje mec&aacute;nico)<br />\n- Lipoescultura sin Cirug&iacute;a<br />\n- Depilaci&oacute;n Definitiva<br />\n- Mesoterapia<br />\n- Radiofrecuencia Tripolar&nbsp;<br />\n- Radiofrecuencia Fraccionada (estr&iacute;as)<br />\n- Body Sculpt&nbsp;<br />\n- Drenaje Linf&aacute;tico Manual<br />\n- Masajes descontracturantes con Piedras calientes<br />\n- Day Spa<br />\n- Hidrataci&oacute;n y Exfoliaci&oacute;n corporal</p>\n\n<p>&nbsp;</p>\n\n<p>&nbsp;</p>\n',2),(4054,69,'Tratamientos Faciales','<p>- Higiene Facial Profunda + Microdermoabrasi&oacute;n con punta de diamante<br />\n- Hidrataci&oacute;n + Black Mask<br />\n- Peeling + Microdermoabrasi&oacute;n con punta de diamante<br />\n- Radiofrecuencia Tripolar<br />\n- Radiofrecuencia Fraccionada (Frax Face)<br />\n- Plasma cosmetol&oacute;gico (Electroporaci&oacute;n)<br />\n- Tratamiento PB Serum (a base de enzimas)<br />\n- Mascara LED<br />\n- Alta Frecuencia / Ozonoterapia<br />\n- Luz Pulsada<br />\n- Ulthera (HIFU)<br />\n- Mesoterapia<br />\n- Botox / Rellenos / Skinbooster<br />\n&nbsp;</p>\n',3),(4055,69,'GIFT VOUCHER','<p>Aprovech&aacute; nuestro Gift Voucher para sorprender a alguien especial con un regalo super original !!! Obsequi&aacute; un Day Spa o alguno de nuestros tratamientos faciales y corporales.<br />\n&nbsp;</p>\n',4),(4070,33,'Descripción','<p>Venga y disfrute de una atenci&oacute;n personalizada en todos nuestros servicios: Tratamientos faciales y corporales, masajes, aromaterapia, manicuria, pedicuria, depilaciones y tratamientos con parafina.<br />\nNuestra principal misi&oacute;n es servirle como usted merece.<br />\n<br />\nLo invitamos a descubrirlo, por qu&eacute; Centro de Est&eacute;tica Carla Levy, es el lugar ideal para vivir un d&iacute;a de paz, tranquilidad, bienestar y belleza.</p>\n',1),(4071,33,'Tratamientos Corporales','<ul>\n	<li>Ultrasonido</li>\n	<li>Presoterapia</li>\n	<li>Termocel</li>\n	<li>Contractor Muscular</li>\n	<li>Interfer</li>\n	<li>Algoterapia</li>\n	<li>Fangoterapia</li>\n	<li>Chocoterapia</li>\n	<li>Radiofrecuencia Corporal</li>\n	<li>Ultracavitaci&oacute;n</li>\n</ul>\n',2),(4072,33,'Tratamientos Faciales','<ul>\n	<li>Limpieza de Cutis Profunda</li>\n	<li>Tratamiento de Acne</li>\n	<li>Radiofrecuencia Facial</li>\n	<li>Peeling con Acido</li>\n	<li>Velo de Colageno</li>\n	<li>Microdermoabraci&oacute;n Punta de Diamante</li>\n	<li>Mascara de Oro</li>\n	<li>Mascara de Ginseng</li>\n	<li>Mascara de Aloe Vera</li>\n	<li>Mascara de Chocolate</li>\n	<li>Parche de Ojos</li>\n</ul>\n',3),(4073,33,'Masajes','<ul>\n	<li>Masajes Circulatorios</li>\n	<li>Masajes con Piedras Calientes</li>\n	<li>Masajes Descontracturantes</li>\n	<li>Masajes Hidratantes</li>\n	<li>Masajes Relajantes</li>\n	<li>Drenaje Linfatico Manual</li>\n	<li>Masaje Podal</li>\n</ul>\n',4),(4074,33,'Días de Spa','<ul>\n	<li>Spa Anti-stress y Desintoxicante</li>\n	<li>Spa Facial Antiage</li>\n	<li>Spa Revitalizante</li>\n	<li>Spa Piernas Cansadas</li>\n	<li>Spa Novias</li>\n	<li>Spa Descontracturante</li>\n	<li>Spa Embarazadas</li>\n	<li>Spa Hombre/Mujer</li>\n	<li>Spa Mama</li>\n	<li>Spa Narciso</li>\n	<li>Spa Renovar</li>\n	<li>Spa Super Relax</li>\n	<li>Spa Vida</li>\n	<li>Spa &quot;Complex&quot;</li>\n	<li>Spa &quot;Chocolate Facial &amp; corporal&quot;</li>\n	<li>Spa Beauty</li>\n	<li>Spa Gold</li>\n	<li>Spa Shock Total</li>\n	<li>Spa Weekend</li>\n	<li>Spa 4 Elementos</li>\n</ul>\n',5),(4075,33,'Más Servicios','<ul>\n	<li>Mascara Facial de Aloe Vera</li>\n	<li>MAscara de Ginseng</li>\n	<li>Radiofrecuencia Facial</li>\n	<li>Ultracavitaci&oacute;n corporal</li>\n	<li>Radiofrecuencia Corporal</li>\n	<li>Alisado Permanente con Algas</li>\n	<li>Parche de Ojos</li>\n	<li>Permanente de Pesta&ntilde;as y tintura</li>\n	<li>U&ntilde;as Esculpidas</li>\n	<li>U&ntilde;as Decoradas</li>\n	<li>Extensiones</li>\n</ul>\n',6),(4141,89,'test','<p>test</p>\n',1),(4189,24,'CLIMA DUO','<p style=\"text-align: center;\"><strong>TODAV&Iacute;A TE DEPILAS?<br />\nVOS ELEG&Iacute;S. Tres sistemas con excelentes resultados</strong></p>\n\n<p style=\"text-align: center;\">&nbsp;</p>\n\n<p><strong>CLIMA DUO</strong></p>\n\n<p>Qu&eacute; es CLIMA DUO?<br />\nEs una nueva tecnolog&iacute;a en depilaci&oacute;n, adquirida por Depi4ever en forma exclusiva para todos sus Centros de Atenci&oacute;n. Clima D&uacute;o supera todos los antiguos sistemas ya conocidos, y permite realizar depilaci&oacute;n definitiva en menor tiempo con resultados de excelencia, mediante un tratamiento de tipo cosm&eacute;tico patentado, no invasivo, de baja potencia.</p>\n\n<p>En qu&eacute; consiste el EFECTO DUO?<br />\nClima D&uacute;o + Cuidado Extra de la Piel Es la combinaci&oacute;n del uso de la nueva tecnolog&iacute;a en depilaci&oacute;n junto a productos cosm&eacute;ticos dise&ntilde;ados por Depi4ever para ser usados tanto en las sesiones de depilaci&oacute;n, como en el hogar por cada cliente. Efecto D&uacute;o ayuda a mejorar el aspecto de la piel, a trav&eacute;s de tres pasos recomendados para lograr: una depilaci&oacute;n efectiva + piel perfecta.</p>\n\n<p>Resultados m&aacute;s r&aacute;pido<br />\nClima D&uacute;o elimina el vello en fases an&aacute;genas m&aacute;s tempranas que las que requieren los dem&aacute;s sistemas. De esta manera, podes realizar sesiones con mayor frecuencia (cada 20 d&iacute;as), y reducir los tiempos totales del tratamiento.</p>\n\n<p>Mayor confort<br />\nDepilaci&oacute;n que cuida tu piel.Clima D&uacute;o no agrede la piel, siendo asimilables sus niveles de calor a los de una depilaci&oacute;n con cera. Adem&aacute;s utilizamos menos gel en cada sesi&oacute;n, y de esta manera reducimos la sensaci&oacute;n de fr&iacute;o en las zonas a depilar.*</p>\n\n<p>Mejor piel<br />\n&Uacute;nico tratamiento integral de depilaci&oacute;n desarrollado y enfocado en el cuidado de la piel. El tratamiento incorpora productos desarrollados con hierbas naturales que aportan propiedades terap&eacute;uticas, y cremas Post-Depilaci&oacute;n que refrescan la zona depilada y mejoran el aspecto de la piel, rehidratando y dando suavidad.*</p>\n\n<p>*Estudios realizados por New Medical Tech, Madrid, 2014..</p>\n',1),(4190,24,'Depilación Láser','<p style=\"text-align: center;\"><strong>TODAV&Iacute;A TE DEPILAS?<br />\nVOS ELEG&Iacute;S. Tres sistemas con excelentes resultados</strong></p>\n\n<p>En Depi4ever tambi&eacute;n pod&eacute;s elegir realizar tu depilaci&oacute;n con lo &uacute;ltimo en tecnolog&iacute;a L&aacute;ser.</p>\n\n<p><br />\n&iquest;Qu&eacute; es la Depilaci&oacute;n L&aacute;ser?<br />\nLa Depilaci&oacute;n L&aacute;ser consiste en la utilizaci&oacute;n del sistema de Diodo Laser &ldquo;X-treme HR&rdquo;. Este sistema es realizado con equipos de alta tecnolog&iacute;a, equipados con &ldquo;Skin Safe &reg;&rdquo;, el cual te asegura el mayor confort con la mayor seguridad, en menos sesiones, con la posibilidad de realizarlo incluso en pieles bronceadas.</p>\n\n<p>&iquest;C&oacute;mo funciona?<br />\nEl sistema X-treme HR funciona bajo el nuevo est&aacute;ndar de FHR &ndash; Fast Hair Removal, que act&uacute;a debilitando y/o matando los fol&iacute;culos sin da&ntilde;ar la piel. Por esta misma raz&oacute;n, el tratamiento se puede realizar con piel bronceada y sin sufrir dolor alguno.</p>\n\n<p>&iquest;Cu&aacute;l es la diferencia entre los distintos sistemas de depilaci&oacute;n?<br />\nLa elecci&oacute;n depende de la comodidad, presupuesto, gusto y elecci&oacute;n de cada persona. Los 3 sistemas tienen excelente resultados.</p>\n\n<p>&nbsp;</p>\n',2),(4191,24,'Luz Pulsada','<p style=\"text-align: center;\"><strong>TODAV&Iacute;A TE DEPILAS?<br />\nVOS ELEG&Iacute;S. Tres sistemas con excelentes resultados</strong></p>\n\n<p style=\"text-align: center;\">&nbsp;</p>\n\n<p><strong>Luz Pulsada</strong></p>\n\n<p>El tratamiento de Depilaci&oacute;n por Luz Pulsada consiste en debilitar o destruir los fol&iacute;culos pilosos activos, con el objeto de inhibir o reducir el crecimiento del pelo. Desde las primeras sesiones se ver&aacute;n resultados, siendo la regla general la necesidad de varias sesiones para lograr efectos &oacute;ptimos: se requieren como m&iacute;nimo de 4 a 6 sesiones.</p>\n\n<p>Debido a que los equipos que utilizamos en Depi4ever son de alta tecnolog&iacute;a y totalmente efectivos, solamente dependemos del factor de tu cuerpo: estad&iacute;sticamente se requieren 8 sesiones, que pueden ser mas dependiendo de cada persona, condici&oacute;n en que el cliente se encuentre y medicamentos que pueda estar tomando (las sesiones hacen al tratamiento muy accesible ya que son aproximadamente una vez por mes).<br />\nLos pelos que se matan no vuelven a crecer nunca m&aacute;s. Los que se debilitan se terminan de rematar en las siguientes sesiones, es por eso la importancia de venir a las sesiones en fecha. La luz destruye solo los fol&iacute;culos que est&aacute;n en fase an&aacute;gena. Como el ciclo de crecimiento del pelo no es uniforme (es decir, no crecen todos los pelos al mismo tiempo), es que tenemos que hacer varias sesiones. A partir de la segunda sesi&oacute;n, ya comenzar&aacute;s a ver resultados, y muchas personas ya ven resultados concretos a partir de su primera sesi&oacute;n.<br />\nLas sesiones pueden ser realizadas cada 3 a 5 semanas: normalmente se hace una cada 4 semanas. Para mantener el tratamiento en su &oacute;ptimo resultado, lo recomendable es realizarte sesiones de refuerzo que dependen de cada persona. Y si tienes problemas de foliculitis o pelos encarnados, el problema se soluciona de ra&iacute;z, ya que al no haber fol&iacute;culo ni pelo, no se puede inflamar ni encarnar. Si quer&eacute;s realizar tu tratamiento en la zona del rostro, el mismo suele necesitar mas sesiones.</p>\n',3),(4210,58,'Descripción','<p><strong>ID.ESTETICA</strong> es un consultorio que ofrece UNA PROPUESTA DIFERENTE. Creemos que el sentirse bien es importante tanto para hombres como mujeres y contamos con equipamiento de avanzada que, junto al buen criterio profesional y a los avances tecnol&oacute;gicos de la medicina est&eacute;tica, nos permite fusionar:</p>\n\n<p><strong>SALUD, BELLEZA, TECNOLOGIA Y BIENESTAR.</strong></p>\n\n<p>En ID ESTETICA tenemos un enfoque integral de la persona, atendiendo su salud y cuidando su imagen. Especializados profesionales brindan a los pacientes tratamientos m&eacute;dicos-kin&eacute;sicos actualizados y pone a disposici&oacute;n las &uacute;ltimas innovaciones en cirug&iacute;as.</p>\n\n<p>&nbsp;</p>\n\n<p><strong>Nuestro concepto de CALIDAD se basa en la EXCELENCIA, DEDICACI&Oacute;N Y ATENCI&Oacute;N PERSONALIZADA.</strong></p>\n\n<p>CONSULTA SIN CARGO</p>\n',1),(4211,58,'Tratamientos Corporales','<p>- Lipol&aacute;ser - Modelaci&oacute;n Corporal - Celulitis</p>\n\n<p>- Criolip&oacute;lisis - Reduce Adiposidades</p>\n\n<p>- Adiposidad Localizada- Hidrolipoclasia</p>\n\n<p>- Liporeducci&oacute;n - Fosfatidilcolina</p>\n\n<p>- Lipocel - Ultracavitaci&oacute;n</p>\n\n<p>- Celulitis - Celushock</p>\n\n<p>- Termoterapia - Termocel</p>\n\n<p>- Presoterapia Secuencial</p>\n\n<p>- Flaccidez Cut&aacute;nea y Muscular</p>\n\n<p>- Radiofrecuencia Corporal Profunda</p>\n\n<p>- Corrientes Rusas e Interferenciales</p>\n\n<p>- Mesoterapia Corporal</p>\n\n<p>- Estr&iacute;as |Tratamiento M&eacute;dico Kin&eacute;sico</p>\n\n<p>- Ara&ntilde;itas - Telangiectasias - L&aacute;ser</p>\n\n<p>- Masajes Kin&eacute;sicos - Descontracturantes - Taping</p>\n\n<p>- Post Quir&uacute;rgico Corporal</p>\n\n<p>- Mam&aacute;s Postparto</p>\n',2),(4212,58,'Tratamientos Faciales','<p>- Arrugas Faciales - Toxina Botul&iacute;nica</p>\n\n<p>- Radiofrecuencia Facial</p>\n\n<p>- Rellenos- Hialur&oacute;nicos</p>\n\n<p>- Plasma Rico en Plaquetas</p>\n\n<p>- Mesolifting - Mesoface</p>\n\n<p>- Peeling Qu&iacute;mico - Cosmi&aacute;trico M&eacute;dico</p>\n\n<p>- Fotorejuvenecimiento L&aacute;ser - Ara&ntilde;itas Faciales</p>\n\n<p>- Microdermoabrasi&oacute;n - Puntas de Diamante</p>\n\n<p>- Cosmetolog&iacute;a - Limpieza de Cutis</p>\n\n<p>- Refreshing - Humectaci&oacute;n - Nutrici&oacute;n</p>\n\n<p>- Flaccidez Muscular Facial - Electro Estimulaci&oacute;n Facial</p>\n\n<p>- Drenaje Linf&aacute;tico Facial - Ros&aacute;cea</p>\n\n<p>- Post Quir&uacute;rgico Facial</p>\n\n<p>- L&aacute;ser ND: YAG&nbsp; Manchas - Lesiones Pigmentadas</p>\n',3),(4213,58,'Cirugia Plástica','<p>La Cirug&iacute;a Pl&aacute;stica es una especialidad m&eacute;dica que combina el ARTE y la CIENCIA, el primero es la b&uacute;squeda de la belleza, y la satisfacci&oacute;n de quien la contempla, la ciencia fundamental para diagnosticar y comprender las respuestas del cuerpo humano a los distintos tratamientos.</p>\n\n<p>- Cirug&iacute;a de Nariz- Rinoplast&iacute;a</p>\n\n<p>- Cirug&iacute;a de P&aacute;rpados - Blefaroplast&iacute;a</p>\n\n<p>- Cirug&iacute;a de Orejas Prominentes - Otoplast&iacute;a</p>\n\n<p>- Lifting y Minilifting Facial</p>\n\n<p>- Implantes Mamarios</p>\n\n<p>- Reducci&oacute;n Mamaria - Hipertrofia Mamaria</p>\n\n<p>- Lipoescultura Ultras&oacute;nica -Lipoaspiraci&oacute;n</p>\n\n<p>- Abdominoplast&iacute;a - Dermolipectomia</p>\n\n<p>- Lifting de Brazos y Muslos</p>\n\n<p>- Aumento Gl&uacute;teo &ndash; Gluteoplast&iacute;a</p>\n\n<p>- Cirug&iacute;a Post Bari&aacute;trica - Post Adelgazamiento</p>\n\n<p>- Cirug&iacute;a Post Maternidad</p>\n',4),(4776,46,'Descripción','<p>Celtic es un multiespacio, que naci&oacute; con el objetivo de ofrecer servicios y tendencias de cuidado personal, y bienestar general. Queremos ayudarte a verte bien, y sentirte mejor. Queremos que encuentres todos tus intereses de cuidado personal, relax, look, belleza, y decoraci&oacute;n, en un mismo lugar que te identifique!<br />\nCELTIC cuenta con profesionales, experiencia, y tecnolog&iacute;a para tratar los 3 pu<span class=\"text_exposed_show\">ntos foco en est&eacute;tica: PIEL, TEJIDO, y MUSCULOS. Muchos son los tratamientos que se ofrecen hoy en d&iacute;a gracias a los avances de la tecnolog&iacute;a, y hay aparatolog&iacute;a destinada a cada uno de estos puntos. Pero es importante realizar un buen diagnostico para detectar cual o cuales son los puntos a tratar, y que aparatolog&iacute;a es la indicada en cada caso particular, de lo contrario, in&uacute;til ser&aacute; invertir tiempo y dinero en tratamientos. Cada tratamiento es personalizado, y proponi&eacute;ndonos un objetivo en com&uacute;n para lograr los mejores resultados.<br />\nDespu&eacute;s de dos a&ntilde;os, sumamos CELTIC PELUQUERIA &amp; MAKE UP!, un espacio s&uacute;per exclusivo y personalizado, de la mano de Romina Bustos!<br />\nY adem&aacute;s, inauguramos un Showroom de decoraci&oacute;n, donde te acercamos ideas y tendencias para decorar tus espacios, y que puedas disfrutar tu estad&iacute;a a pleno! CH Tienda Deco es la nueva propuesta by Celtic Home, y estamos seguros te va a encantar!<br />\nLos invitamos a conocer CELTIC y a comprobarlo por ustedes mismos.</span></p>\n',1),(4777,46,'Tratamientos','<p>- Ondas Rusas e Interferenciales</p>\n\n<p>- Peeling</p>\n\n<p>- Depilaci&oacute;n sistema descartable</p>\n\n<p>- Depilaci&oacute;n Definitiva</p>\n\n<p>- Limpieza Facial</p>\n\n<p>- Spa de Manos</p>\n\n<p>- Spa de Pies</p>\n\n<p>- Esmaltado</p>\n\n<p>- Radiofrecuencia Tripolar</p>\n\n<p>&nbsp;</p>\n',2),(4844,27,'Descripción','<p>Un complejo dedicado a la salud y est&eacute;tica, que all&aacute; por el a&ntilde;o 2000 en un almuerzo entre reconocidos profesionales del medio, exponiendo valiosas ideas para mejorar la salud y la belleza de sus pacientes, surge la idea de crear un Instituto que brinde estos servicios, en el mismo, cada uno de ellos aportar&aacute; lo mejor de s&iacute; para llegar a concretar dicho fin.<br />\nEl primer paso fue encontrar un lugar f&iacute;sico donde desarrollar la importante y valiosa experiencia adquirida en cl&iacute;nicas de reconocido nombre a nivel nacional como as&iacute; tambi&eacute;n internacional.<br />\nAs&iacute; fue como surgi&oacute; nuestra casa central sita en - Capital Federal, con filiales en Chile y en Espa&ntilde;a<br />\nDe esta manera, queremos llegar a ustedes y poder brindarles todos nuestros conocimientos para el desarrollo de lo expuesto, ya que para nosotros lo mas importante es la atenci&oacute;n a nuestros pacientes.<br />\nA continuaci&oacute;n ustedes empezaran a recorrer todas nuestras &aacute;reas donde explicamos detalladamente los sistemas y m&eacute;todos de c&oacute;mo realizamos nuestros tratamientos.<br />\nComo as&iacute; tambi&eacute;n esperamos que nos escriban donde de esta manera podremos contestar todas vuestras inquietudes.</p>\n',1),(4845,27,'Estética','<p>- CELULITIS:<br />\nEstudios y diagn&oacute;sticos de los diferentes grados de celulitis - Tratamientos avanzados. OBESIDAD: Causas, tipos, diagn&oacute;stico y tratamientos - Determinaci&oacute;n de peso y talla.</p>\n\n<p>LESIONES ELEMENTALES DE LA PIEL:<br />\nM&aacute;cula, p&aacute;pula, n&oacute;dulo, ves&iacute;cula, ampolla, p&uacute;stula, escama, costra, cicatriz, atrofia y esclerosis.</p>\n\n<p>TRATAMIENTO CAPILAR:<br />\nMesoterapia capilar, mesoterapia<br />\n(aplicaci&oacute;n intrad&eacute;rmica de medicamentos).</p>\n\n<p>EMBELLECIMIENTO DE GL&Uacute;TEOS Y BUSTOS.<br />\nExfoliacion corporal, limpieza profunda de cutis, mascaras faciales, dermopigmentacion</p>\n',2),(4846,27,'Aparatología','<p>Onda Corta<br />\nUltrasonido<br />\nIontoforesis<br />\nMultiplex<br />\nElectroestimulador<br />\nCold-Hot<br />\nDermopress<br />\nL&aacute;ser<br />\nL&aacute;mpara Ultravioleta<br />\n&aacute;mpara Infrarroja<br />\nRadofrecuencia Tripolar<br />\nUltracavitador<br />\nOndas Rusas<br />\nOxiface<br />\nC&aacute;psula Derrmoactiva de ozono<br />\nC&aacute;psula termobiodinamica<br />\nMesoterapia Mecanica<br />\nMesoterapia Virtual<br />\nPermanente de pesta&ntilde;as</p>\n',3),(4965,60,'Descripción','<p>LP-Mbelleze es un centro de est&eacute;tica que se especializa en t&eacute;cnicas no invasivas. Nuestra misi&oacute;n es tu bienestar. LPMbelleze te Cuida!&nbsp;</p>\n\n<p>Junto a todo mi equipo de profesionales, contamos con la &uacute;ltima tecnolog&iacute;a en aparatolog&iacute;a y con una atenci&oacute;n personalizada y privada.</p>\n\n<p>Para mayor informaci&oacute;n visitanos en: <a href=\"http://www.lp-mbelleze.com.ar/\">www.lp</a>mbelleze.com&nbsp;y seguinos en: Instagram: @lpmbelleze y en Facebook: @lpmbellezeok</p>\n',1),(4966,60,'Tratamientos Corporales','<p>- Hifu &ndash; Ultrasonido focalizado (brazos, abdomen, pierna subgl&uacute;teo y pantal&oacute;n de montar)<br />\n- Carboxiterapia (brazos, piernas, abdomen, gl&uacute;teos, rodilla)<br />\n- Estr&iacute;as<br />\n- Modelaci&oacute;n Corporal<br />\n- Celulitis<br />\n- Adiposidad Localizada<br />\n- Flaccidez<br />\n- Tratamiento Post Parto<br />\n- Pulido Corporal<br />\n- Hidrataci&oacute;n<br />\n- Lipoescultura&nbsp; Sin Cirug&iacute;a<br />\n- Tratamiento Crioterapia<br />\n- Tratamiento Fango-Terapia<br />\n- Tratamiento Yeso-Terapia<br />\n- Drenaje Linf&aacute;tico Manual<br />\n- Tonificaci&oacute;n Muscular<br />\n- Dermopigmentaci&oacute;n<br />\n- Acupuntura</p>\n',2),(4967,60,'Tratamientos Faciales','<p>- Hifu &ndash; Ultrasonido focalizado &ndash; Lifting facial Sin Cirug&iacute;a<br />\n- Carboxiterapia<br />\n- Hidrataci&oacute;n y revitalizaci&oacute;n<br />\n- Higiene profunda<br />\n- Lifting sin cirug&iacute;a<br />\n- Peeling cosmetol&oacute;gico, mec&aacute;nico y qu&iacute;mico<br />\n- M&aacute;scaras seg&uacute;n biotipo de piel<br />\n- Tratamiento antiage<br />\n- Tatamiento Yeso-Terapia<br />\n- Rejuvenecimiento<br />\n- Reafirmaci&oacute;n</p>\n',3),(4968,60,'Medicina Estética','<p>- Carboxiterapia<br />\n- Frenolog&iacute;a<br />\n- Peeling M&eacute;dicos<br />\n- Rellenos<br />\n- Botox&reg;<br />\n- Plasma rico en plaquetas (PRP)<br />\n- Mesoterapia<br />\n- Magnetoterapia<br />\n- Electroanalgecia</p>\n',4),(4969,60,'Servicios','<div class=\"tab-pane fade active in\" id=\"tab_3\" role=\"tabpanel\">\n<p><strong>Masajes:</strong><br />\n- Masaje kinesiol&oacute;gico y terap&eacute;utico<br />\n- Masaje con piedras calientes</p>\n\n<p><strong>Asesoria de Imagen:</strong><br />\n- Cambios de Look<br />\n- Potencia tu Imagen<br />\n- colorimetria personal</p>\n\n<p>-Guardarropas a Medida</p>\n\n<p><strong>Extensi&oacute;n de pesta&ntilde;as:</strong><br />\n- Pelo natural<br />\n- Pelo x pelo<br />\n- Seda Premium<br />\n- T&eacute;cnica 3D</p>\n\n<p><strong>Aparatolog&iacute;a:</strong><br />\n- Hifu &ndash; Ultrasonido focalizado<br />\n- Radiofrecuencia<br />\n- Ultrasonido<br />\n- Presoterapia<br />\n- Ondas Rusas<br />\n- Ondas Interferenciales<br />\n- Cavitaci&oacute;n<br />\n- Punta De Diamante<br />\n- Microdermoabrasi&oacute;n</p>\n</div>\n',5),(4994,54,'Descripción','<p>Mas Plena es un lugar &uacute;nico para nosotras, un lugar para estar en forma, por dentro y por fuera, encontrar el relax y la serenidad.</p>\n',1),(4995,54,'Tratamientos Corporales','<p>- Criolipolisis<br />\n- Ultracavitacion<br />\n- Mesoterapia corpor<br />\n-Radiifrecuencia<br />\n- Ondas rusas<br />\n- Electroporaci&oacute;n<br />\n- Presoterapia<br />\n- Termoterapia<br />\n-Depilacion definitiva<br />\n- Microdermabraci&oacute;n<br />\n<br />\n&nbsp;</p>\n\n<p>&nbsp;</p>\n',2),(4996,54,'Tratamientos Faciales','<p>-Hi-fu<br />\n- Peeling qu&iacute;mico o combinado<br />\n- Radiofrecuencia tripolar<br />\n- Electroporaci&oacute;n<br />\n- Fotorejuvenecimiento<br />\n- Plasma rico en plaquetas</p>\n\n<p><br />\n&nbsp;</p>\n\n<p>&nbsp;</p>\n',3),(4997,54,'Fotorejuvenecimiento','<p>El fotorejuvenecimiento por Luz Pulsada es un tratamiento no invasivo que mejora de una manera natural y efectiva los signos visibles del envejecimiento cut&aacute;neo provocado por el paso del tiempoy fundamentalmente por los efectos nocivos del sol (arrugas de expresi&oacute;n, manchas, ros&aacute;ceas, telangiestasias, etc), obteniendo como resultado una piel sana, tersa y m&aacute;s joven. Este tratamiento consiste en aplicar pulsos de Luz Intensa que penetran en la epidermis, sin da&ntilde;arla pero estimulando el nuevo col&aacute;geno y la elastina para mejorar la calidad de la piel. Se puede aplicar en rostro, escote, cuello y manos. Es un tratamiento indoloro y no se requiere tiempo de recuperaci&oacute;n.</p>\n',4),(4998,54,'Spa y Masajes','<p><strong>* Spa Agua: </strong>Limpieza de Cutis + Hidrataci&oacute;n + Masaje Relajante de Espalda (1 y 1/2 horas)</p>\n\n<p><strong>* Spa Brisa: </strong>Masaje Relajante (30 minutos) + Peelin Mec&aacute;nico o radiofrecuencia Facial (a elecci&oacute;n) + Hidrataci&oacute;n + M&aacute;scara (seg&uacute;n biotipo)</p>\n\n<p><strong>* Spa Rocio: </strong>Masaje Integral (1 hora) + Fangoterapia + Hidrataci&oacute;n Facial con ADN</p>\n\n<p>&nbsp;</p>\n\n<p><strong>MASAJES</strong></p>\n\n<p>Masajes descontracturantes y/o relajantes</p>\n\n<p>&nbsp;</p>\n',5),(5039,40,'Descripción','<p>En <strong>D&eacute;rmica</strong> vas a encontrar un centro de est&eacute;tica moderno, profesional y en constante actualizaci&oacute;n donde, en un ambiente c&aacute;lido y contenedor, podr&aacute;s concretar ese cambio que est&aacute;s deseando.<br />\n<br />\nSomos una empresa joven, atendido por m&aacute;dicas, especializada en tratamientos est&eacute;ticos faciales y corporales.<br />\n<br />\nContamos con un equipo interdisciplinario de profesionales de la medicina est&eacute;tica y lo &uacute;ltimo en tecnolog&iacute;a para ofrecer un servicio personalizado que contemple las necesidades, caracter&iacute;sticas y deseos de cada uno de los pacientes.<br />\n<br />\nNuestro objetivo es brindar tratamientos integrales que logren la armon&iacute;a corporal, teniendo en cuenta siempre la salud y el bienestar de la persona.</p>\n',1),(5040,40,'Tratamientos Faciales','<ul>\n	<li>Peeling m&eacute;dico</li>\n	<li>Punta de diamante</li>\n	<li>Fraxface - Radiofrecuencia fraccionada</li>\n	<li>HIFU</li>\n	<li>Mesolifting</li>\n	<li>Limpieza facial profunda</li>\n	<li>Fotorejuvenecimiento con IPL</li>\n	<li>Acn&eacute;</li>\n	<li>Ros&aacute;cea</li>\n	<li>Hiperpigmentaci&oacute;n (manchas)</li>\n	<li>M&aacute;scaras faciales</li>\n	<li>Plasma rico en plaquetas</li>\n	<li>Rellenos con hialur&oacute;nico</li>\n	<li>Botox</li>\n	<li>Radiofrecuencia tripolar</li>\n	<li>Medicina Orthomolecular</li>\n</ul>\n',2),(5041,40,'Tratamientos Corporales','<ul>\n	<li>Ultracavitaci&oacute;n CAVIX</li>\n	<li>Lipolisis con Fosfatidilcolina</li>\n	<li>Presoterapia</li>\n	<li>Electroestimulaci&oacute;n</li>\n	<li>Criolipolisis</li>\n	<li>Mesoterapia</li>\n	<li>Ondas de choque</li>\n	<li>Masajes reductores</li>\n	<li>Masajes relajantes/descontracturantes</li>\n	<li>Exfoliaci&oacute;n corporal</li>\n	<li>HIFU</li>\n	<li>Reflexolog&iacute;a</li>\n	<li>Radiofrecuencia tripolar</li>\n	<li>carboxiterapia</li>\n	<li>Depilaci&oacute;n laser Soprano</li>\n</ul>\n',3),(5042,47,'Descripción','<p>Est&eacute;tica Integral&nbsp; (atenci&oacute;n ambos sexos)</p>\n\n<p>Atenci&oacute;n personalizada, gabinete calefaccionado, con buena m&uacute;sica para que se puedan relajar y olvidar por un rato de todos los problemas.</p>\n\n<div>\n<p>&nbsp;Profesionales a cargo:</p>\n\n<p>&nbsp;Ver&oacute;nica Pizarro, Alejandra Jelicanin&nbsp;y Ver&oacute;nica&nbsp; Falasca.</p>\n</div>\n\n<p><br />\nLos productos utilizados en el gabinete est&aacute;n a la venta.<br />\n<br />\nSi traes una amiga, agregale&nbsp; una sesi&oacute;n de regalo a tu tratamiento.</p>\n\n<div>\n<p>En el gabinete adem&aacute;s pod&eacute;s encontrar para ropa deportiva, remeras, calzas, pantuflas, ropa interior, medias etc. Todo de muy buena calidad y a precios accesibles.</p>\n</div>\n\n<div>\n<p><strong>VF</strong> &nbsp;te ofrece entrar en el mundo de la vibraci&oacute;n con el servicio de plataforma vibratoria cuyos beneficios son:</p>\n\n<p style=\"margin-left:18pt;\">&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <strong>Combatir la celulitis</strong></p>\n\n<p style=\"margin-left:18pt;\">&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <strong>Mejorar la circulaci&oacute;n y el drenaje linf&aacute;tico</strong></p>\n\n<p style=\"margin-left:18pt;\">&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <strong>Tonificar los m&uacute;sculos</strong></p>\n\n<p style=\"margin-left:18pt;\">&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <strong>Mejorar el equilibrio</strong></p>\n\n<p style=\"margin-left:18pt;\">&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <strong>Mejorar la flexibilidad</strong></p>\n\n<p style=\"margin-left:18pt;\">&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <strong>Ayudar los niveles de cortisol (Hormona del Stress)</strong></p>\n\n<p style=\"margin-left:18pt;\">&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <strong>Aumentar la densidad mineral &oacute;sea</strong></p>\n\n<p style=\"margin-left:18pt;\">&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <strong>Eliminar grasas</strong></p>\n\n<p style=\"margin-left:18pt;\">&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <strong>Mejorar el estado f&iacute;sico</strong></p>\n\n<p style=\"margin-left:18pt;\">&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <strong>Modelar</strong></p>\n</div>\n',1),(5043,47,'Tratamientos','<p><strong>- PLATAFORMA VIBRATORIA</strong><br />\nentra en el mundo de la vibraci&oacute;n con el nuevo servicio de plataforma vibratoria cuyos beneficios son:</p>\n\n<p>&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Combatir la celulitis<br />\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Mejorar la circulaci&oacute;n y el drenaje linf&aacute;tico<br />\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Tonificar los m&uacute;sculos<br />\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Mejorar el equilibrio<br />\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Mejorar la flexibilidad<br />\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Ayudar los niveles de cortisol (Hormona del Stress)<br />\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Aumentar la densidad mineral &oacute;sea<br />\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Eliminar grasas<br />\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Mejorar el estado f&iacute;sico<br />\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Modelar</p>\n\n<p>&nbsp;</p>\n\n<p><strong>- ELECTROESTIMULACION(electrodos)</strong><br />\nIncluye el programa de ondas rusas<br />\nEl tratamiento de electroestimulaci&oacute;n es una t&eacute;cnica reconocida cient&iacute;ficamente que act&uacute;a por medio de contracciones musculares. Estas contracciones permiten que los m&uacute;sculos adquieran volumen, fuerza, tono y resistencia, adem&aacute;s trabaja aquellas zonas de grasa localizada de una manera muy efectiva.</p>\n\n<p>Se presenta como una opci&oacute;n muy eficaz contra la flaccidez que consiste en la colocaci&oacute;n de electrodos, a lo largo de los m&uacute;sculos afectados, dando como resultado el fortalecimiento muscular como si fuera una gimnasia pasiva. Sus efectos son altamente reafirmantes, produce una acelerada reducci&oacute;n de medidas y disminuye la flaccidez de los tejidos.</p>\n\n<p>El tratamiento de electroestimulaci&oacute;n es ideal para prevenir o mejorar la &quot;celulitis est&eacute;tica&quot;, padecida por la mayor&iacute;a de mujeres, no es otra cosa que una modificaci&oacute;n sufrida por el tejido conjuntivo por la acumulaci&oacute;n de grasa, l&iacute;quidos y toxinas.</p>\n\n<p>Los turnos se piden por tel o v&iacute;a mail. Los d&iacute;as de atenci&oacute;n son de Lunes a S&aacute;bado.</p>\n\n<p><br />\n<strong>- MASOTERAPIA (masajes descontracturantes y relajantes)<br />\n<br />\n- COSMETOLOG&Iacute;A</strong>(limpieza de cutis profunda con extracci&oacute;n de comedones, humectaci&oacute;n, tonificaci&oacute;n, m&aacute;scara para cada tipo de piel y masajes faciales).<br />\n<br />\n<strong>- REFLEXOLOG&Iacute;A<br />\n<br />\n- MASAJE THAILAND&Eacute;S<br />\n<br />\n- MAQUILLAJE<br />\n<br />\n- PULIDO CORPORAL<br />\n<br />\n- ULTRASONIDO<br />\n<br />\n- CIRCUITO DE CINTA, PLATAFORMA VIBRATORIA Y ELECTRODOS</strong></p>\n',2),(5044,52,'Descripción','<p><span data-mce-mark=\"1\"><span class=\"style21\"><strong>Doral Esthetic es un centro integral de belleza y bienestar.</strong><br />\nEs un lugar especialmente pensado para que encuentres la mejor versi&oacute;n de vos mismo, acompa&ntilde;ado por los mejores profesionales de est&eacute;tica, fitness y nutrici&oacute;n.<br />\nEn Doral pod&eacute;s entrenar y embellecer tu cuerpo, relajar la mente y elevar tu esp&iacute;ritu.<br />\nTomate un tiempo para compartir con amigos, pareja o simplemente encontrarte con vos. </span></span></p>\n\n<p>Promos Para Mam&aacute;</p>\n',1),(5045,52,'Tratamientos','<p>Los tratamientos que se ofrecen dependiendo cada programa son:</p>\n\n<p>&nbsp;</p>\n\n<p>● Depilaci&oacute;n Definitiva SOPRANO</p>\n\n<p>● Masajes</p>\n\n<p>● Ultracavitaci&oacute;n (elimina adiposidad localizada)</p>\n\n<p>● Mesoterapia con o sin agujas</p>\n\n<p>● Ondas Rusas (tonificaci&oacute;n y modelaci&oacute;n)</p>\n\n<p>● C&aacute;psula Termobiodin&aacute;mica (termoadelgazamiento, tonificaci&oacute;n, drenaje linf&aacute;tico)</p>\n\n<p>● C&aacute;psula dermoactiva de ozono (afecciones cut&aacute;neas)</p>\n\n<p>● Sauna Seco con Cromoterapia (elimina toxinas)</p>\n\n<p>● Drenaje linf&aacute;tico manual</p>\n\n<p>● Ozonoterapia (afeccciones reum&aacute;ticas, articulares, varices, ara&ntilde;itas, revitalizaci&oacute;n biol&oacute;gica, tratamientos de&nbsp;acn&eacute;, celulitis, estr&iacute;as, etc)</p>\n\n<p>● Radiofrecuencia (rejuvenecimiento facial y corporal)</p>\n\n<p>● Microdermoabrasi&oacute;n con punta de diamante (limpieza de cutis mec&aacute;nica)</p>\n\n<p>● Oxiface (oxigenacion celular facial, anti-acn&eacute;, anti age)</p>\n\n<p>● M&aacute;scaras revitalizantes</p>\n\n<p>● Otros Servicios: * Spa y Belleza de Manos y de Pi&eacute;s *</p>\n',2),(5054,34,'Estética Facial','<p><span data-mce-mark=\"1\"><span data-mce-mark=\"1\"><span data-mce-mark=\"1\"><span data-mce-mark=\"1\"><strong>&middot;</strong> Tratamiento Telagectsias (Rosacea)<br />\n<span data-mce-mark=\"1\"><span data-mce-mark=\"1\"><span data-mce-mark=\"1\"><span data-mce-mark=\"1\"><span data-mce-mark=\"1\"><span data-mce-mark=\"1\"><span data-mce-mark=\"1\"><span data-mce-mark=\"1\"><strong>&middot;</strong> </span></span></span></span>Tratamiento</span></span></span></span>&nbsp;de Acne<br />\n<span data-mce-mark=\"1\"><span data-mce-mark=\"1\"><span data-mce-mark=\"1\"><span data-mce-mark=\"1\"><span data-mce-mark=\"1\"><span data-mce-mark=\"1\"><span data-mce-mark=\"1\"><span data-mce-mark=\"1\"><strong>&middot;</strong> </span></span></span></span>Tratamiento</span></span></span></span> manchas<br />\n<span data-mce-mark=\"1\"><span data-mce-mark=\"1\"><span data-mce-mark=\"1\"><span data-mce-mark=\"1\"><span data-mce-mark=\"1\"><span data-mce-mark=\"1\"><span data-mce-mark=\"1\"><span data-mce-mark=\"1\"><strong>&middot;</strong> </span></span></span></span>Tratamiento</span></span></span></span>&nbsp;con celulas madres<br />\n<span data-mce-mark=\"1\"><span data-mce-mark=\"1\"><span data-mce-mark=\"1\"><span data-mce-mark=\"1\"><strong>&middot;</strong> </span></span></span></span>Plasma<br />\n<span data-mce-mark=\"1\"><span data-mce-mark=\"1\"><span data-mce-mark=\"1\"><span data-mce-mark=\"1\"><strong>&middot;</strong> </span></span></span></span>Peeling con acidos combinados<br />\n<span data-mce-mark=\"1\"><span data-mce-mark=\"1\"><span data-mce-mark=\"1\"><span data-mce-mark=\"1\"><strong>&middot;</strong> </span></span></span></span>Puntas de diamantes<br />\n<span data-mce-mark=\"1\"><span data-mce-mark=\"1\"><span data-mce-mark=\"1\"><span data-mce-mark=\"1\"><strong>&middot;</strong> </span></span></span></span>Radiofrecuencia tripolar<br />\n<span data-mce-mark=\"1\"><span data-mce-mark=\"1\"><span data-mce-mark=\"1\"><span data-mce-mark=\"1\"><strong>&middot;</strong> </span></span></span></span>Fotorejuvenecimiento con IPL<br />\n<span data-mce-mark=\"1\"><span data-mce-mark=\"1\"><span data-mce-mark=\"1\"><span data-mce-mark=\"1\"><strong>&middot;</strong> </span></span></span></span>Mesolifting<br />\n<span data-mce-mark=\"1\"><span data-mce-mark=\"1\"><span data-mce-mark=\"1\"><span data-mce-mark=\"1\"><strong>&middot;</strong> </span></span></span></span>Electroporaci&oacute;n</span></span></span></span></p>\n\n<p><span data-mce-mark=\"1\"><span data-mce-mark=\"1\"><span data-mce-mark=\"1\"><span data-mce-mark=\"1\">&nbsp; Skinbooster</span></span></span></span></p>\n\n<p><span data-mce-mark=\"1\"><span data-mce-mark=\"1\"><span data-mce-mark=\"1\"><span data-mce-mark=\"1\">&nbsp;Tratamiento Ortomolecular con peptonas</span></span></span></span></p>\n\n<p>&nbsp;</p>\n\n<p>&nbsp;</p>\n',1),(5055,34,'Estética Corporal','<p><span data-mce-mark=\"1\"><span data-mce-mark=\"1\"><span data-mce-mark=\"1\"><span data-mce-mark=\"1\"><strong>&middot;</strong> Radiofrecuencia tripolar<br />\n<strong>&middot;</strong> Lipolaser<br />\n<strong>&middot;</strong> Ondas Rusas<br />\n<strong>&middot;</strong> Mesoterapia Reductora, celulitis<br />\n<strong>&middot;</strong> Termoterapia<br />\n<strong>&middot;</strong> Tra de Estrias<br />\n<strong>&middot;</strong> Tra de Araňitas<br />\n<strong>&middot;</strong> Tra de Puntos Rubi<br />\n<strong>&middot;</strong> Reducci&oacute;n tonificaci&oacute;n celulitis flaccidez.</span></span></span></span></p>\n\n<p>&nbsp;</p>\n',2),(5056,34,'Estética Capilar','<p><br />\n<span data-mce-mark=\"1\"><span data-mce-mark=\"1\"><span data-mce-mark=\"1\"><span data-mce-mark=\"1\"><strong>&middot;</strong> Tratamiento para la caida, recuperaciony engrosamiento del cabello</span></span></span></span></p>\n\n<p><span data-mce-mark=\"1\"><span data-mce-mark=\"1\"><span data-mce-mark=\"1\"><span data-mce-mark=\"1\">Mesoterapia Capilar</span></span></span></span></p>\n',3),(5303,106,'Descripción','<p>Somos Piel Libre, un centro de est&eacute;tica ubicado en Ciudad de Buenos Aires dedicado a brindar todo tipo de servicios y tratamientos para la piel y el cuerpo.</p>\n',1),(5304,106,'Tratamientos Corporales','<p>Tratamiento Presoterapia<br />\nDrenaje Linfatico Manual<br />\nTratamientos Reductores<br />\nTratamientos Anticelulitis<br />\nTratamientos Reafirmantes<br />\nTratamientos Circulatorios<br />\nTratamiento de Estrias<br />\nMasajes Descontracturantes<br />\nMasajes Relajantes<br />\nMasajes Cervicales<br />\nMasajes Lumbociatica<br />\nMasajes con Piedras Calientes<br />\nFango Terapia<br />\nCrio Terapia<br />\nReflexologia</p>\n',2),(5305,106,'Tratamientos Faciales','<p>Peeling Facial Punta de Diamante<br />\nPeeling Facial Acidos<br />\nLimpieza de Cutis<br />\nTratamientos Hidro-Nutritivos<br />\nTratamientos Antiage<br />\nTratamientos Acn&eacute;<br />\nTratamiento Rosacea</p>\n',3),(5306,106,'Depilación y otros servicios','<p>Depilaci&oacute;n Cera Descartable<br />\nDepilaci&oacute;n Cera Vegetal<br />\nCama Solar<br />\nManicuria y Belleza de Manos<br />\nPedicuria<br />\nColocaci&oacute;n de Aros<br />\nMaquillaje Social-Novias</p>\n\n<p>&nbsp;</p>\n',4),(5437,15,'Descripción','<p>Innovamos en est&eacute;tica. Somos un equipo que analizamos las tendencias del mundo, que d&iacute;a a d&iacute;a se van renovando e incorporando nuevas t&eacute;cnicas. Para lograr que tanto la mujer como el hombre, reflejen su mente j&oacute;ven, en su rostro y cuerpo. Deteniendo de una manera inteligente el deterioro producido por la agitada vida que llevamos.</p>\n\n<p>&nbsp;</p>\n',1),(5438,15,'Aparatología High Tech','<p>- Ultracavitaci&oacute;n<br />\n- Radiofrecuencia<br />\n- Presoterapia<br />\n- Vacunterapia<br />\n- Luminoterapia<br />\n- Ondas Simetricas<br />\n&nbsp;</p>\n',2),(5439,15,'Cosmiatría para rostro y cuerpo','<p>- Facial LAB<br />\n- Radiofrecuencia + higiene profunda</p>\n\n<p>-&nbsp; Radiofrecuencia + higiene profunda + punta de diamante.<br />\n- Facial Anti- age<br />\n- Foto Rejuvenecimiento</p>\n\n<p>-Tratamiento para patolog&iacute;as (An&eacute;, Ros&aacute;cea, pieles hiperpigmentadas).</p>\n\n<p>- Peeling facial y corporal.</p>\n\n<p>- Tratamiento Franc&eacute;s exfoliante y nutritivo.</p>\n\n<p>&nbsp;</p>\n\n<p><br />\n&nbsp;</p>\n',3),(5440,15,'Más Tratamientos','<p><strong>*</strong> Mujer Party Time | minimo 4 mujeres<br />\n<strong>* </strong>Unisex Oficina | minimo 10 personas<br />\n<strong>*</strong> Hombre Facial | Milennium Man<strong>.</strong><br />\n<strong>*</strong> Pilates<br />\n<strong>*</strong> Plataformas Vibratorias</p>\n',4),(5441,15,'Masajes y DLM','<p>- Drenaje Linf&aacute;tico corporal y Facial</p>\n\n<p>- Masajes descontracturantes / Ayurv&eacute;dicos / relajantes / Terapeuticos.</p>\n\n<p>- Reflexolog{ia</p>\n',5),(5442,15,'Kits Spa','<p>- Evasion Holistic</p>\n\n<p>- Un souffle de energie</p>\n\n<p>- Mision Evasion</p>\n\n<p>- Jour Esthetique</p>\n',6),(5443,15,'NAIL SPA','<p>BELLEZA DE MANOS Y PIES</p>\n\n<p>ESMALTADO SEMIPERMANENTE</p>\n\n<p>U&Ntilde;AS ESCUPIDAS</p>\n',7),(5454,72,'Descripción','<p><strong>Tr&egrave;s Belle</strong> es un centro de Fotodepilaci&oacute;n y Medicina Est&eacute;tica, que cuenta con profesionales altamente calificados en el sector de la belleza facial y corporal.</p>\n\n<p>Tr&egrave;s Belle destaca por su atenci&oacute;n personalizada, la calidad humana de su equipo y la idoneidad de sus especialistas que, unidos al empleo de tecnolog&iacute;a de avanzada, pone al alcance de sus pacientes los tratamientos corporales y faciales m&aacute;s eficaces, garantizando una alta satisfacci&oacute;n en los resultados obtenidos.</p>\n\n<p>Nuestros equipos cuentan con certificaciones de ANMAT (Administraci&oacute;n Nacional de Medicamentos, Alimentos y Tecnolog&iacute;a), Comunidad Europea, Normas ISO 9001 y F.D.A (Food and Drug Administration), prestigiosa entidad que regula los medicamentos y tratamientos m&eacute;dicos en los EEUU.</p>\n',1),(5455,72,'Tratamientos Faciales','<p>En TRES BELLE&nbsp; ofrecemos una amplia variedad de&nbsp; tratamientos faciales para quienes desean mejorar el aspecto de su rostro de forma natural.</p>\n\n<p>- Thermage<br />\n- Peelings dermatol&oacute;gicos y cosmetol&oacute;gicos<br />\n- Toxina Botulimica 1&deg; marca<br />\n- Plasma rico en plaquetas<br />\n- Microdermoabrasi&oacute;n por puntas de diamante<br />\n- Triatherm radiofrecuencia tripolar<br />\n- Topicaciones<br />\n- Rellenos faciales<br />\n- Limpieza de cutis e hidrataci&oacute;n<br />\n- Limpieza de cutis profunda<br />\n- Mascaras tensoras, hidratantes, descongestivas, anti age, anti acn&eacute;<br />\n- Depilaci&oacute;n Definitiva<br />\n- Tratamiento de acn&eacute; y ros&aacute;cea<br />\n- Tratamiento para ojeras<br />\n- Fotorrejuvenecimiento IPL<br />\n- Mesoterapia facial<br />\n- Radiofrecuencia m&eacute;dica-lifting sin cirug&iacute;a</p>\n',2),(5456,72,'Tratamientos Corporales','<p>ANTICELULITIS-REDUCTORES-REAFIRMANTES-MODELADORES<br />\nOfrecemos una amplia variedad de tratamientos contra la celulitis, adiposidad localizada,estr&iacute;as, flaccidez y v&aacute;rices entre otras opciones. Con el respaldo de las mejores marcas en aparatolog&iacute;a m&eacute;dico-est&eacute;tica, todo lo necesario para modelar tu cuerpo,verte y sentirte espl&eacute;ndida. En Tres Belle&nbsp; encontrar&aacute;s soluciones a tu medida.</p>\n\n<p>- Mesoterapia<br />\n- Lipoactive 90 -Ultracavitaci&oacute;n<br />\n- Criolipolisis-Lipocell Crio<br />\n- Plasma rico en plaquetas<br />\n- Radiofrecuencia Tripolar<br />\n- Mesoterapia sin agujas<br />\n- Fosfatidilcolina<br />\n- Hidrolipoclasia<br />\n- Lipasa<br />\n- Presoterapia secuencial<br />\n- Ultrasonido<br />\n- Electroestimulaci&oacute;n (ondas rusas)<br />\n- Microdermoabrasi&oacute;n con puntas de diamante<br />\n- Depilaci&oacute;n Devinitiva<br />\n- Masajes reductores<br />\n- Masajes reafirmantes<br />\n- Masajes modeladores<br />\n- Drenaje linf&aacute;tico manual</p>\n',3),(5457,72,'Servicios','<p><strong>Depilaci&oacute;n Definitiva IPL</strong><br />\n&iexcl;Piel suave y libre de vellos!<br />\nSeguimiento m&eacute;dico dermat&oacute;logico permanente<br />\nTecnol&oacute;gia de avanzada Elight IPl + RF<br />\nRespaldados por TECNOIMAGEN<br />\nResultados desde las primeras sesiones</p>\n\n<p><strong>Relax:</strong><br />\nEn TRES BELLE encontrar&aacute;s la combinaci&oacute;n perfecta de armon&iacute;a y relajaci&oacute;n,<br />\nen un ambiente lejos del estr&eacute;s y las obligaciones, para recrear la<br />\ncalidad de vida y bienestar que tanto merec&eacute;s.</p>\n\n<p>Masajes descontracturantes<br />\nMasajes relajantes<br />\nChocoterapia<br />\nReiki<br />\nChi kung<br />\nMindfulness (Meditaci&oacute;n)</p>\n\n<p><strong>Vouchers de regalo:</strong><br />\nUn regalo innovador, para que las personas que vos<br />\nquieras disfruten de TRES BELLE. Un lugar c&aacute;lido, confortable, con<br />\ndetalles de categor&iacute;a y atenci&oacute;n personalizada.<br />\nRegala nuestras promociones, masajes u otros tratamientos.</p>\n',4),(5520,21,'Descripción','<p>En nuestros consultorios se aplican las t&eacute;cnicas m&aacute;s novedosas y actuales en el campo de la dermatolog&iacute;a est&eacute;tica, con aparatolog&iacute;a de &uacute;ltima generaci&oacute;n. Estas t&eacute;cnicas deben estar indicadas y aplicadas bajo un estricto criterio m&eacute;dico, individualizado en cada paciente, para ofrecer un programa global de tratamiento y obtener los resultados esperados.<br />\n<br />\nNuestro objetivo es lograr que cada paciente conozca y cuide su piel durante todo el a&ntilde;o y que los excelentes resultados obtenidos perduren en el tiempo.<br />\n<br />\nAtenci&oacute;n personalizada y un equipo de profesionales altamente capacitados realizan los tratamientos acordes a cada situaci&oacute;n del paciente.</p>\n',1),(5521,21,'Tratamientos Faciales','<p>- Accent Facial<br />\n- Carboxiterapia<br />\n- Plasma Rico en Plaquetas<br />\n- Mesoterapia<br />\n- Luz Pulsada<br />\n- Peelings<br />\n- Radiofrecuencia<br />\n- Microdermoabrasi&oacute;n</p>\n',2),(5522,21,'Tratamientos Corporales','<p>- VelaShape II<br />\n- Carboxiterapia<br />\n- Accent Corporal<br />\n- Plasma Rico en Plaquetas<br />\n- Radiofrecuencia<br />\n- Ultracavitaci&oacute;n<br />\n- Soprano XL 3G<br />\n- Mesoterapia</p>\n',3),(5523,21,'Tratamientos Capilares','<p>- Mesoterapia Capilar<br />\n- Carboxiterapia Capilar<br />\n- Plasma Rico en Plaquetas Capilar</p>\n',4),(5542,16,'Descripción','<p>Centro de Est&eacute;tica y Medicina Especializado en Tratamientos Corporales,Faciales Masajes, Mesoterapia nutrici&oacute;n, reiki y Moda</p>\n',1),(5543,16,'Tratamientos','<p>- Ondas Rusas y Ultrasonido</p>\n\n<p>- Shock Rejuvenecimiento Facial Profundo</p>\n\n<p>- Masajes y Presoterapia</p>\n\n<p>- Reiki</p>\n\n<p>- Clases de Pilate y Yoga</p>\n\n<p>- Nutricionista</p>\n',2),(5599,100,'Descripción','<p>En <strong>YM</strong> entendemos y respetamos tus tiempos, lo com&uacute;n es la falta del mismo para todas! Trabajo, familia, profesi&oacute;n, etc. Ocupan un tiempo considerado en nuestras agendas y adem&aacute;s necesitamos estar impecables 24 hs; por este motivo creamos un sistema de atenci&oacute;n simultanea donde pod&eacute;s combinar los servicios que elijas al mismo tiempo en un ambiente de lujo y relax en el cual profesionalismo y atenci&oacute;n personalizada son nuestra filosof&iacute;a. Te invitamos a disfrutar de esta experiencia a la cual tenemos el honor de llamar luxurybeauty&amp;relax&reg;</p>\n',1),(5600,100,'Cejas','<p><strong>Las cejas marcan la diferencia!</strong></p>\n\n<p>Muchas veces notamos una mirada cansada, triste, notamos nuestros parpados demasiados ca&iacute;dos, una mirada apagada sin vida, si esto te esta inquietando, tan solo con un dise&ntilde;o y color en cejas esto puede solucionarse.<br />\nTambi&eacute;n t&eacute;cnicas semipermanentes de relleno como la MICROPIGMENTACION o el MICROBLADING o EXTENSIONES DE CEJAS donde el faltante de pelitos es notable, donde los arcos ya est&aacute;n desdibujados, cuando a tu mirada le falta fuerza.</p>\n\n<p>En YM asesoramos a cada mujer seg&uacute;n sus necesidades, su d&iacute;a, su vida, porque todas somos diferentes y cada una necesitamos diferentes soluciones es que tenemos todas las herramientas posibles para brindarte la que m&aacute;s te simplifique, solo con una consulta podemos buscar la soluci&oacute;n adecuada.</p>\n\n<p>&nbsp;</p>\n\n<p style=\"margin-left: 40px;\">&bull; Microblading</p>\n\n<p style=\"margin-left: 40px;\">&bull; Shading y Ombre</p>\n\n<p style=\"margin-left: 40px;\">&bull; Estensiones de Cejas</p>\n\n<p style=\"margin-left: 40px;\">&bull; Perfilado, Dise&ntilde;o y Color de Cejas</p>\n',2),(5601,100,'Extensiones de Pestañas','<p><strong>Miradas que Enamoran!</strong></p>\n\n<p>Las Extensiones de Pesta&ntilde;as son fibras sint&eacute;ticas, que vienen sueltas, individuales, pelo por pelo, de diferentes texturas, formas, arqueados, colores y tama&ntilde;os. Tienen una ra&iacute;z y una punta, imitando las pesta&ntilde;as naturales en forma. La innovadora tecnolog&iacute;a con microporos&reg; permite que Se unan mediante un adhesivo, aprobado por los organismos de salud, una a una a tus pesta&ntilde;as naturales y no a la piel como las pesta&ntilde;as postizas convencionales de sal&oacute;n de belleza, dejando que las propias respiren naturalmente.&nbsp; Esto hace que no sean perjudiciales a la salud, respetando y acompa&ntilde;ando el ciclo de crecimiento y ca&iacute;da natural que todos tenemos</p>\n\n<p>A diferencia de las Pesta&ntilde;as Postizas tradicionales, con las Extensiones de Pesta&ntilde;as pelo por pelo podr&aacute;s: Ir a piscina - Ir al mar - Hacer tu rutina diaria de gimnasio - usar lentes de contacto</p>\n\n<p>TECNICAS</p>\n\n<p style=\"margin-left: 40px;\">&bull; Extensiones Pelo por Pelo<br />\n&bull; Extensiones HD 0 Volumen Ruso<br />\n&bull; Arqueado y pigmentaci&oacute;n de pesta&ntilde;as &quot;LIFT LASHES&quot;</p>\n',3),(5602,100,'Más Servicios','<p><strong>MAQUILLAJE</strong><br />\n&ldquo;esa fabulosa ilusi&oacute;n &oacute;ptica que todas necesitamos&rdquo;</p>\n\n<p>Social, novias, fiestas Para esos momentos de tu vida que necesitas lucir esplendida nada mejor que la ayuda de un profesional, para una fiesta, un evento importante, ser anfitriona, siempre hay un momento que queremos lucir incre&iacute;bles!<br />\n<br />\n<strong>EST&Eacute;TICA FACIAL</strong><br />\ntu rostro tambi&eacute;n necesita estar fresco, limpio e hidratado te ofrecemos un facial con punta de diamantes, productos espec&iacute;ficos a cada tipo de piel y todos los beneficios del drenaje linf&aacute;tico manual para desintoxicar, descongestionar y darle luminosidad el cual tambi&eacute;n podes realizar en tu cuerpo proporcionandote un relax exquisito, &uacute;nico.<br />\n<br />\n<strong>MANICURA</strong><br />\nCon personal experto, con las &uacute;ltimas tendencias en colores, con productos de primera l&iacute;nea como Opi, Sally Hansen, Channel, Dior, Marc Jacobs, etc.<br />\nDISfruta de un momento &uacute;nico de relax mientras aplicas tus extensiones!</p>\n\n<p>Tambi&eacute;n podes realizar tus U&Ntilde;AS GELIFICADAS y/o con ESMALTE SEMIPERMANENTE OPIGEL para una duraci&oacute;n mas extensa!</p>\n\n<p>Incorporamos el Servicio de U&ntilde;as esculpidas en GEL y NAIL ART, Disfruta de un verano lleno de color y diversi&oacute;n!</p>\n\n<p>&nbsp;</p>\n\n<p><strong>DIAS ESPECIALES</strong></p>\n\n<p>&nbsp;</p>\n\n<p><strong>LIVE LOVE LASH</strong><br />\nEn solo dos horas, cinco servicios al mismo tiempo. Tres profesionales trabajan aplicando tus extensiones de pesta&ntilde;as. Limpieza facial con punta de diamente e hidratacion, para que tu piel luzca fresca y radiante m&aacute;s todos los beneficios del drenaje linf&aacute;tico con bota de presoterapia. Tus manos y pies impecables con el color que elijas. Ideal para relajarte, optimizar tus tiempos y verte espl&eacute;ndida*</p>\n\n<p>Tambien podes realizar estse servicio con Lifting y Color de pesta&ntilde;as, asi como Manicuria y belleza de pies en gel.<br />\n&nbsp;</p>\n\n<p><strong>COOL ON THE WEEK</strong><br />\nEn un d&iacute;a de semana puede surgirte una cena o evento en el cual quieras lucir diferente&hellip; radiante en poco tiempo, este servicio es ideal, en solo 1 hora 30 aplicamos tus extensiones de pesta&ntilde;as, con manicur&iacute;a y maquillaje incluido!<br />\n&nbsp;</p>\n\n<p><strong>BEAUTY EXPRESS</strong><br />\nEn solo una hora y media realiza tu mantenimiento o colocaci&oacute;n de extensiones&nbsp; de pesta&ntilde;as y disfruta de manicuria OPI GEL para una duraci&oacute;n de 2 semanas impecables!<br />\n&nbsp;</p>\n\n<p><strong>BACHERLORETTE PARTY</strong><br />\nPara el d&iacute;a que va a ser tu momento, el d&iacute;a mas especial de tu vida, tenemos asesoramiento personalizado para novias ese d&iacute;a en que necesitas que todo sea perfecto que mejor que una beauty expert para sincronizar todos los detalles de tu est&eacute;tica para ese d&iacute;a.<br />\nCompart&iacute; esta experiencia &uacute;nica con tu grupo de amigas, ideal para juntas disfrutar de unas horas de relax, mimos, belleza y diversi&oacute;n!<br />\n&nbsp;</p>\n\n<p><strong>GIFT CARDS</strong><br />\nTodas estas experiencias podes compartirlas a modo de obsequio con tus amigas y familiares queridos.&nbsp; Cons&uacute;ltanos y te sugerimos la que mejor se pueda adaptar a ellas seg&uacute;n su perfil para agasajarlas en su cumplea&ntilde;os, aniversarios, reconocimientos, d&iacute;as especiales etc!</p>\n',4),(5603,62,'Descripción','<p>En el coraz&oacute;n de Caballito abre sus puertas Millow, centro de est&eacute;tica, cuya &uacute;nica consigna es el bienestar de cuerpo y el alma a trav&eacute;s de diferentes tratamientos especialmente dise&ntilde;ados para cada necesidad.</p>\n\n<p>Apenas se cruza la entrada de MILLOW, el tiempo parece detenerse. Hay opciones completas para cuerpo, rostro y cabello. Sesiones de est&eacute;tica, peelings, microdermoabrasion con punta de diamantes, tratamientos anticelulitis, talasoterapia (con algas), panes anti-age y tratamientos capilares entre otros.</p>\n\n<p>Para quienes necesiten un alto en medio del estr&eacute;s urbano, Millow brinda servicios de masaje con piedras calientes, tratamientos orientales, cromoterapia, reiki y shiatzu.</p>\n\n<p>:: Millow es el lugar donde solo entran vos, tu cuerpo y tu mente<br />\nRegalate ese momento y dejate tentar ::</p>\n',1),(5604,62,'Tratamientos','<p><strong>TRATAMIENTOS CORPORALES</strong></p>\n\n<p>- Masajes reductores<br />\n- Masajes circulatorios (reducci&oacute;n)<br />\n- Drenaje linf&aacute;tico manual<br />\n- Exfoliaci&oacute;n e hidrataci&oacute;n<br />\n- Tratamiento corporal con algas, chocolate, vino y fango</p>\n\n<p>&nbsp;</p>\n\n<p><strong>TRATAMIENTOS FACIALES</strong></p>\n\n<p>- Limpieza facial profunda<br />\n- Peelings<br />\n- Tratamientos para acn&eacute;<br />\n- Mesolifting<br />\n- Hidrataci&oacute;n anti envejecimiento<br />\n- Microdermoabrasi&oacute;n con punta de diamante<br />\n- Ozonoterapia<br />\n- M&aacute;scaras (tensoras, anti age, fangos, oro, cobre, chocolate, frambuesa...)<br />\n- Tratamientos Capilares<br />\n- Control de ca&iacute;da y recuperaci&oacute;n de pelo</p>\n\n<p><br />\n<strong>APARATOLOGIA</strong></p>\n\n<p>- Electroterapia (contractores)<br />\n- Presoterapia Secuencial<br />\n- RadioFrecuencia<br />\n- VacummTerapia<br />\n- Electroporaci&oacute;n (Mesoterapia sin Aguja)<br />\n- Termoterapia, termocel (bandas t&eacute;rmicas)<br />\n- Ultrasonido<br />\n- Ozonoterapia<br />\n- Iontoforesis<br />\n- Camilla Termal<br />\n- Sonotrioterapia (tratamiento que combina la terapia por ultrasonido y la terapia por frio)<br />\n- Miotonic (activador muscular mediante el empleo de radioterapia basada en corrientes cim&eacute;tricas)</p>\n',2),(5605,62,'Servicios','<p>- Masajes para contracturas agudas y cr&oacute;nicas<br />\n- Masaje descontracturante y relajante<br />\n- Geoterapia (piedras)<br />\n- Reflexolog&iacute;a<br />\n- Cromoterapia<br />\n- Reiki<br />\