INSERT INTO `spa_questions_responses` VALUES (1,1,14,'ok!','2019-06-19 22:48:23',0),(2,3,495,'Hola Gabriela,\r\nGracias por tu consulta!\r\nA continuación te detallo Nuestros Days Spa.\r\n\r\n\r\nPROMO 2 X 1 \r\nMasaje localizado sedativos- antiestrés\r\nMasaje ayurveda hindú\r\n(Masajes en trapecios,cuello,cabeza,facial)\r\nReflexología + masajes de pies\r\nLimpieza facial\r\nDuración: 75 min\r\nValor: $2000\r\n--------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------\r\n.Experiencia profunda\r\n\r\nMasajes corporales integrales. (descontracturantes - relajantes,cuerpo completo, ambos lados).\r\nMasajes energéticos con cañas de bambú.\r\nStretching corporal (alivia dolores musculares y de articulaciones, mejora la postura)\r\nReflexología y masajes de pies.\r\nLimpieza facial rostro y escote.\r\nInfusión. \r\nDuración 120 minutos.\r\nValor $2500 (por persona) \r\n---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------\r\nEspecial Choco Relax Duo  \r\n\r\nLa chocoterapia  es una Técnica  que reconforta el cuerpo a la vez que estimula los sentidos a través  de las propiedades del Cacao. Proporciona placer y es beneficioso para el organismo.\r\n\r\nMasajes Descontracturantes + Chocoterapia + Reflexología Integral + Limpieza facial +  Copa de Champagne \r\n\r\nDuración : 150 minutos.\r\nValor  Individual : $ 2500      Valor por pareja : $ 4600\r\n\r\n\r\nMasaje  Asiático con Cañas de Bambú.\r\n\r\nLas cañas de Bambú  son empleadas  sobre el cuerpo. Además de hacer  un suave masaje , logran que la energía  de nuestro cuerpo empiece a fluir \r\n\r\nMasaje Descontracturantes + Masajes energéticos con Cañas de Bambú + Esencias  aromáticas  Afrodisíacas + Reflexología  Integral 